struct OrderNode {
    Order order; // The trade details
    std::atomic<OrderNode*> next; // Atomic pointer
    std::atomic<int> state; // Node state
};

class LockFreeOrderBook {
    std::atomic<OrderNode*> head; // Top of the book
public:
    void push(Order order) {
        while (true) {
            // 1. Take a snapshot of the head
            OrderNode* old_head = head.load();
            // 2. Prepare the new node
            OrderNode* node = new OrderNode{order, old_head, 0};
            // 3. Atomically attempt to swap it in
            if (head.compare_exchange_weak(old_head, node))
                break; // Success!
        }
    }
    Order pop() {
        while (true) {
            // 1. Take a snapshot of head
            OrderNode* old_head = head.load();
            if (!old_head) return Order(0, 0, 0, false);
            // 2. Attempt to point head to the next node
            if (head.compare_exchange_weak(old_head, 
                old_head->next.load())) {
                Order res = old_head->order;
                // 3. Delete old node (Hazard Pointers needed for true safety)
                delete old_head;
                return res; // Success!
            }
        }
    }
};
